    Effect.gen(function* () {
      const catalogue = yield* exampleContentCatalogue;
      yield* Effect.forEach(catalogue.pages, (page) =>
        Effect.forEach(
          [
            {
              ...page,
              frontmatter: { ...page.frontmatter, status: "draft" },

