                          HttpClientRequest.toWeb(request, { signal }).pipe(
                            Effect.flatMap((incoming) =>
                              Effect.tryPromise({
                                catch: () => new DocsRpcUnavailable(),
                                try: () =>
                                  settings.binding.fetch(incoming, { signal }),
                              })
                            ),
                            Effect.flatMap(
                              Schema.decodeUnknownEffect(
                                Schema.instanceOf(Response)
