import "@tanstack/react-start/server-only";
import { collectionPolicyFromHeaders } from "@taxkit/analytics/collection-policy";
import { CollectionPolicyHeader } from "@taxkit/analytics/schemas";
import { TaxKitApi } from "@taxkit/api-http/api";
import {
  CalculatorClientRateKey,
  CalculatorRequestRateKey,
} from "@taxkit/api-rpc/rate-identity";
import { CalculatorAdmissionUnavailable } from "@taxkit/calculators/schemas";
import { fromCloudflareFetcher, toHttpClient } from "alchemy/Cloudflare/Bridge";
import { toRpcAsync } from "alchemy/Cloudflare/Bridge";
import type { TaxKitApiWorker } from "api/worker";
import {
  Context,
  Effect,
  Layer,
  Option,
  Redacted,
  Result,
  Schema,
} from "effect";
import {
  HttpClient,
  HttpClientError,
  HttpClientRequest,
  HttpClientResponse,
  HttpServerRequest,
} from "effect/http";
import { HttpApiClient } from "effect/http-api";
import { NetAddress } from "effect/net";

import { TaxKitWebConfigError } from "../config";
import { TaxKitWebServerConfig } from "../config.server";
import type { WebsitePublicSettings } from "../schemas";
import { boundedResponses } from "./bounded-response";
import { WebsiteApiUnavailable } from "./errors";
import type { TaxKitClient } from "./requests";

/**
 * The Website server's host capabilities: its checked settings, the native
 * generated API client over the private same-stage binding, and one finished
 * forward for API-owned downloads.
 */
export class WebsiteHost extends Context.Service<
  WebsiteHost,
  {
    readonly settings: Result.Result<
      WebsitePublicSettings,
      TaxKitWebConfigError
    >;
    readonly client: Result.Result<TaxKitClient, TaxKitWebConfigError>;
    readonly forward: (
      path: string
    ) => Effect.Effect<Response, WebsiteApiUnavailable | TaxKitWebConfigError>;
  }
>()("taxkit/web/WebsiteHost") {}

// Native Alchemy bindings: the selected keys only, with protected values
// unwrapped by Alchemy's own reader. The binding object keeps its receiver.
export const WebsiteHostLive = Layer.effect(
  WebsiteHost,
  Effect.gen(function* () {
    const checked = yield* TaxKitWebServerConfig.pipe(Effect.result);
    const client = yield* Effect.fromResult(checked).pipe(
      Effect.map((config) => {
        const localKey =
          config.hostMode === "local-emulator" &&
          config.apiOrigin.protocol === "http:" &&
          (config.apiOrigin.hostname === "127.0.0.1" ||
            config.apiOrigin.hostname === "localhost")
            ? Schema.decodeUnknownOption(CalculatorClientRateKey)("127.0.0.1")
            : Option.none();
        const reads = toHttpClient(fromCloudflareFetcher(config.binding));
        const privateApi = toRpcAsync<typeof TaxKitApiWorker>(config.binding);
        // Calculation is the Website's only POST. It uses the trusted private
        // method so the original caller's key travels outside JSON and headers.
        // That native method cannot carry an AbortSignal; the API bounds its
        // own work and reply.
        const trusted = HttpClient.make((request) =>
          CalculatorRequestRateKey.pipe(
            Effect.map(Option.orElse(() => localKey)),
            Effect.flatMap(
              Option.match({
                onNone: () =>
                  Effect.fail(
                    new HttpClientError.HttpClientError({
                      reason: new HttpClientError.TransportError({
                        cause: new CalculatorAdmissionUnavailable(),
                        request,
                      }),
                    })
                  ),
                onSome: (key) =>
                  HttpClientRequest.toWeb(request).pipe(
                    Effect.flatMap((incoming) =>
                      Effect.tryPromise({
                        catch: () => new CalculatorAdmissionUnavailable(),
                        try: () =>
                          privateApi.calculatorRequest(
                            incoming,
                            NetAddress.formatIp(Redacted.value(key))
                          ),
                      })
                    ),
                    Effect.flatMap(
                      Schema.decodeUnknownEffect(Schema.instanceOf(Response))
                    ),
                    Effect.map((response) =>
                      HttpClientResponse.fromWeb(request, response)
                    ),
                    Effect.mapError(
                      () =>
                        new HttpClientError.HttpClientError({
                          reason: new HttpClientError.TransportError({
                            cause: new CalculatorAdmissionUnavailable(),
                            request,
                          }),
                        })
                    )
                  ),
              })
            )
          )
        );
        const http = HttpClient.make((request) =>
          request.method === "POST"
            ? trusted.execute(request)
            : reads.execute(request)
        ).pipe(
          // Forward the visitor's collection preference; a server call with no
          // incoming request refuses collection.
          HttpClient.mapRequestEffect((outgoing) =>
            Effect.serviceOption(HttpServerRequest.HttpServerRequest).pipe(
              Effect.map((incoming) =>
                HttpClientRequest.setHeader(
                  outgoing,
                  CollectionPolicyHeader,
                  Option.match(incoming, {
                    onNone: () => "deny",
                    onSome: (request) =>
                      collectionPolicyFromHeaders(request.headers),
                  })
                )
              )
            )
          ),
          boundedResponses
        );
        return {
          binding: config.binding,
          client: HttpApiClient.makeWith(TaxKitApi, {
            baseUrl: config.apiOrigin,
            httpClient: http,
          }),
          settings: config,
        };
      }),
      Effect.flatMap(({ binding, client, settings }) =>
        client.pipe(
          Effect.map((generated) => ({ binding, generated, settings }))
        )
      ),
      Effect.result
    );
    return WebsiteHost.of({
      client: Result.map(client, ({ generated }) => generated),
      forward: (path) =>
        Effect.fromResult(client).pipe(
          Effect.flatMap(({ binding, settings }) =>
            Effect.tryPromise({
              catch: () => new WebsiteApiUnavailable(),
              try: (signal) =>
                binding.fetch(new URL(path, settings.apiOrigin).href, {
                  signal,
                }),
            })
          )
        ),
      settings: Result.map(client, ({ settings }) => ({
        apiOrigin: settings.apiOrigin,
        publicationOrigin: settings.publicationOrigin,
        websiteOrigin: settings.websiteOrigin,
      })),
    });
  })
);

import "@tanstack/react-start/server-only";
import { CalculatorHostMode } from "@taxkit/api-rpc/rate-identity";
import { reifyBoundConfigProvider } from "alchemy/Runtime";
import type { TaxKitApiBinding } from "api/worker";
import {
  Config,
  ConfigProvider,
  Context,
  Effect,
  Predicate,
  Record,
  Schema,
  Struct,
} from "effect";

import { TaxKitWebConfigError } from "./config";
import { WebsitePublicSettings } from "./schemas";

/** The raw Cloudflare bindings object, supplied once by the server host. */
export class WebsiteBindings extends Context.Service<
  WebsiteBindings,
  Readonly<Record<string, unknown>>
>()("taxkit/web/WebsiteBindings") {}

// This is the native SDK capability boundary. Preserve the original Fetcher
// object (and method receiver); a Struct would copy its methods off the binding.
const PrivateApiBinding: Schema.Codec<TaxKitApiBinding> =
  Schema.declare<TaxKitApiBinding>(
    (value): value is TaxKitApiBinding =>
      Predicate.isObject(value) &&
      Predicate.hasProperty(value, "fetch") &&
      Predicate.isFunction(value.fetch) &&
      Predicate.hasProperty(value, "connect") &&
      Predicate.isFunction(value.connect) &&
      Predicate.hasProperty(value, "calculatorRequest") &&
      Predicate.isFunction(value.calculatorRequest)
  );

// Only Website-owned settings reach Config. Alchemy's reader unwraps its
// protected binding format; nothing here inspects those markers itself.
const websiteKeys = [
  "API_PUBLIC_ORIGIN",
  "CALCULATOR_HOST_MODE",
  "POSTHOG_CAPTURE_TOKEN",
  "POSTHOG_COLLECTION_MODE",
  "POSTHOG_PROJECT_ID",
  "POSTHOG_REGION",
  "POSTHOG_STAGE",
  "TAXKIT_PUBLICATION_ORIGIN",
  "WEBSITE_PUBLIC_ORIGIN",
] as const;

export const websiteConfigProvider = WebsiteBindings.pipe(
  Effect.map((bindings) => {
    const selected = Struct.pick(bindings, websiteKeys);
    return reifyBoundConfigProvider(
      ConfigProvider.fromUnknown(selected),
      selected
    );
  })
);

export const TaxKitWebServerConfig = Effect.gen(function* () {
  const bindings = yield* WebsiteBindings;
  const provider = yield* websiteConfigProvider;
  return yield* Effect.all({
    apiOrigin: Config.schema(
      WebsitePublicSettings.fields.apiOrigin,
      "API_PUBLIC_ORIGIN"
    ),
    binding: Schema.decodeUnknownEffect(PrivateApiBinding)(
      Record.get(bindings, "TAXKIT_API")
    ),
    hostMode: Config.schema(CalculatorHostMode, "CALCULATOR_HOST_MODE").pipe(
      Config.withDefault("edge")
    ),
    publicationOrigin: Config.schema(
      WebsitePublicSettings.fields.publicationOrigin,
      "TAXKIT_PUBLICATION_ORIGIN"
    ),
    websiteOrigin: Config.schema(
      WebsitePublicSettings.fields.websiteOrigin,
      "WEBSITE_PUBLIC_ORIGIN"
    ),
  }).pipe(Effect.provideService(ConfigProvider.ConfigProvider, provider));
}).pipe(
  Effect.mapError(
    () =>
      new TaxKitWebConfigError({
        message: "TaxKit web settings are missing or invalid.",
        operation: "settings",
        runtime: "server",
      })
  )
);

