import "@tanstack/react-start/server-only";
import { setResponseStatus } from "@tanstack/react-start/server";
import { CalculatorHostTelemetryLive } from "@taxkit/api-rpc/host-telemetry";
import { CalculatorCatalogResponse } from "@taxkit/calculators/schemas";
import type { DocsPagePath } from "@taxkit/content/schemas";
import { env } from "cloudflare:workers";
import {
  Cause,
  ConfigProvider,
  Effect,
  Layer,
  ManagedRuntime,
  Schema,
} from "effect";
import { FetchHttpClient } from "effect/http";

import { WebsiteAnalyticsRelayLive } from "./analytics/relay/relay.adapter.layer";
import { WebsiteHost, WebsiteHostLive } from "./api/host.server";
import {
  readCatalogue,
  readDocsPage,
  readDocsSearch,
} from "./api/requests";
import { WebsiteBindings, websiteConfigProvider } from "./config.server";
import { DocsSearchInputError } from "./docs/errors";
import { preloadDocsPresentation } from "./docs/mdx.boundary";
import { loadFailureStatus, rejectRouteLoad } from "./load.failure";
import { WebsitePublicSettings } from "./schemas";
import type { WebsiteDocsSearchQuery } from "./schemas";

const bindings = Layer.succeed(WebsiteBindings, env);

// One server runner per loaded Worker module. It supplies native API clients
// and the analytics relay, never a backend implementation; each request
// supplies its own signal.
export const appRuntime = ManagedRuntime.make(
  Layer.mergeAll(
    WebsiteHostLive,
    CalculatorHostTelemetryLive("website"),
    WebsiteAnalyticsRelayLive.pipe(
      Layer.provide(FetchHttpClient.layer),
      Layer.provide(Layer.unwrap(Effect.map(websiteConfigProvider, ConfigProvider.layer)))
    )
  ).pipe(Layer.provide(bindings))
);

// Server loads report their HTTP status before TanStack renders the native
// not-found or error component. Cancellation stays interruption.
const rejectServerLoad = <E>(cause: Cause.Cause<E>) =>
  Cause.hasInterruptsOnly(cause)
    ? Effect.failCause(cause)
    : Effect.sync(() => setResponseStatus(loadFailureStatus(cause))).pipe(
        Effect.andThen(rejectRouteLoad(cause))
      );

const client = WebsiteHost.pipe(
  Effect.flatMap((host) => Effect.fromResult(host.client))
);

export const loadRoot = ({ signal }: Readonly<{ signal: AbortSignal }>) =>
  appRuntime.runPromise(
    Effect.gen(function* () {
      const host = yield* WebsiteHost;
      const settings = yield* Effect.fromResult(host.settings).pipe(
        Effect.flatMap(Schema.encodeEffect(WebsitePublicSettings))
      );
      // The catalogue is optional page chrome; its absence is shown in place.
      const catalogue = yield* client.pipe(
        Effect.flatMap(readCatalogue),
        Effect.flatMap(Schema.encodeEffect(CalculatorCatalogResponse)),
        Effect.option
      );
      return { catalogue, settings };
    }).pipe(Effect.catchCause(rejectServerLoad)),
    { signal }
  );

export const loadDocsPage = ({
  path,
  signal,
}: Readonly<{ path: DocsPagePath; signal: AbortSignal }>) =>
  appRuntime.runPromise(
    Effect.gen(function* () {
      const host = yield* WebsiteHost;
      const settings = yield* Effect.fromResult(host.settings);
      const { navigation, page } = yield* readDocsPage(yield* client, path);
      yield* preloadDocsPresentation(page);
      return {
        navigation,
        page,
        publicationOrigin: settings.publicationOrigin.href,
      };
    }).pipe(Effect.catchCause(rejectServerLoad)),
    { signal }
  );

export const loadDocsSearch = ({
  query,
  signal,
}: Readonly<{ query: WebsiteDocsSearchQuery; signal: AbortSignal }>) =>
  appRuntime.runPromise(
    Effect.gen(function* () {
      const term = yield* Effect.fromResult(query);
      if (term === "") {
        const navigation = yield* client.pipe(
          Effect.flatMap((generated) => generated.content.getNavigation())
        );
        return { navigation, results: [], term };
      }
      const found = yield* readDocsSearch(yield* client, term);
      return { ...found, term };
    }).pipe(
      Effect.catchTag("DocsSearchInputError", (error: DocsSearchInputError) =>
        Effect.succeed({ inputError: error.message })
      ),
      Effect.catchCause(rejectServerLoad)
    ),
    { signal }
  );

// Vite disposes this runtime during development reloads.
if (import.meta.hot !== undefined) {
  import.meta.hot.dispose(() => appRuntime.dispose());
}

