import { TaxKitApi } from "@taxkit/api-http/api";
import { Context, Effect, Layer, Option } from "effect";
import {
  FetchHttpClient,
  HttpClient,
  HttpClientError,
  HttpClientRequest,
} from "effect/http";
import * as Atom from "effect/reactivity/Atom";
import * as AtomHttpApi from "effect/reactivity/AtomHttpApi";

import { BrowserCalculatorPolicyLive } from "../calculator-policy.browser.layer";
import type { WebsitePublicSettings } from "../schemas";
import { boundedResponses } from "./bounded-response";

// Root settings seeded once from the server render. They stay alive for the
// registry's lifetime so an idle page keeps its configuration.
export const publicSettingsAtom = Atom.make(
  Option.none<WebsitePublicSettings>()
).pipe(Atom.keepAlive);

// The one application runtime factory. Native service runtimes share it and
// the router/React registry.
export const browserRuntime = Atom.runtime(Layer.empty);

const browserTransportAtom = Atom.make(
  FetchHttpClient.layer.pipe(
    Layer.provide(
      Layer.succeed(FetchHttpClient.RequestInit, {
        credentials: "omit",
        redirect: "error",
      })
    )
  )
).pipe(Atom.keepAlive);

/**
 * The native generated public API client for browser loaders, components and
 * page tools. It owns encoding, decoding and declared errors; replies are
 * read with the Website's 2 MiB bound.
 */
export class ApiClient extends AtomHttpApi.Service<ApiClient>()(
  "taxkit/web/ApiClient",
  {
    api: TaxKitApi,
    httpClient: (get) =>
      Layer.effect(
        HttpClient.HttpClient,
        HttpClient.HttpClient.pipe(
          Effect.map((client) =>
            Option.match(get(publicSettingsAtom), {
              onNone: () =>
                client.pipe(
                  HttpClient.mapRequestEffect((request) =>
                    Effect.fail(
                      new HttpClientError.HttpClientError({
                        reason: new HttpClientError.InvalidUrlError({
                          description: "TaxKit API settings are unavailable",
                          request,
                        }),
                      })
                    )
                  )
                ),
              onSome: (settings) =>
                client.pipe(
                  HttpClient.mapRequest(
                    HttpClientRequest.prependUrl(settings.apiOrigin.origin)
                  ),
                  boundedResponses
                ),
            })
          )
        )
      ).pipe(
        Layer.provide(BrowserCalculatorPolicyLive),
        Layer.provide(get(browserTransportAtom))
      ),
    runtime: browserRuntime.factory,
  }
) {}

// Native retention keeps the client available between route loads and shares
// it with component queries that use `ApiClient.runtime`.
export const apiClientRuntime = ApiClient.runtime.pipe(Atom.keepAlive);

export const browserApiClient = Atom.getResult(apiClientRuntime, {
  suspendOnWaiting: true,
}).pipe(Effect.map(Context.get(ApiClient)));

import { CalculatorCatalogResponse } from "@taxkit/calculators/schemas";
import type { DocsPagePath } from "@taxkit/content/schemas";
import { Effect, Option, Result, Schema } from "effect";
import * as AtomRegistry from "effect/reactivity/AtomRegistry";

import { browserApiClient, publicSettingsAtom } from "./api/client.atoms";
import { readCatalogue, readDocsPage, readDocsSearch } from "./api/requests";
import { TaxKitWebConfigError } from "./config";
import type { WebsiteDocsSearchQuery } from "./docs/search-location.boundary";
import type { LoaderContext } from "./loader-context";
import { rejectRouteLoad } from "./load.failure";
import { WebsitePublicSettings } from "./schemas";

// TanStack creates its router before loaders or React run. This one registry
// is shared by browser loaders and React's RegistryContext.
export const createLoaderRegistry = () => Option.some(AtomRegistry.make());

const settingsUnavailable = new TaxKitWebConfigError({
  message: "TaxKit web settings are missing or invalid.",
  operation: "settings",
  runtime: "client",
});

// TanStack's one browser Promise bridge. It runs a request Effect with the
// shared registry and the loader's own AbortSignal. Route results belong to
// the router; there is no request Atom or second cache.
const runForLoader = <A, E>({
  context,
  effect,
  signal,
}: Readonly<{
  context: LoaderContext;
  effect: Effect.Effect<A, E, AtomRegistry.AtomRegistry>;
  signal: AbortSignal;
}>) =>
  Effect.runPromise(
    Effect.fromOption(context.registry).pipe(
      Effect.mapError(() => settingsUnavailable),
      Effect.flatMap((registry) =>
        effect.pipe(Effect.provideService(AtomRegistry.AtomRegistry, registry))
      ),
      Effect.catchCause(rejectRouteLoad)
    ),
    { signal }
  );

const settings = AtomRegistry.AtomRegistry.pipe(
  Effect.map((registry) => registry.get(publicSettingsAtom)),
  Effect.flatMap(Effect.fromOption),
  Effect.mapError(() => settingsUnavailable)
);

export const loadRoot = (
  request: Readonly<{ context: LoaderContext; signal: AbortSignal }>
) =>
  runForLoader({
    ...request,
    effect: Effect.gen(function* () {
      const current = yield* settings.pipe(
        Effect.flatMap(Schema.encodeEffect(WebsitePublicSettings))
      );
      const catalogue = yield* browserApiClient.pipe(
        Effect.flatMap(readCatalogue),
        Effect.flatMap(Schema.encodeEffect(CalculatorCatalogResponse)),
        Effect.option
      );
      return { catalogue, settings: current };
    }),
  });

export const loadDocsPage = (
  request: Readonly<{
    context: LoaderContext;
    path: DocsPagePath;
    signal: AbortSignal;
  }>
) =>
  runForLoader({
    ...request,
    effect: Effect.gen(function* () {
      const current = yield* settings;
      const client = yield* browserApiClient;
      const { navigation, page } = yield* readDocsPage(client, request.path);
      return {
        navigation,
        page,
        publicationOrigin: current.publicationOrigin.href,
      };
    }),
  });

export const loadDocsSearch = (
  request: Readonly<{
    context: LoaderContext;
    query: WebsiteDocsSearchQuery;
    signal: AbortSignal;
  }>
) =>
  runForLoader({
    ...request,
    effect: Result.match(request.query, {
      onFailure: () => Effect.succeed({ _tag: "InvalidSearch" as const }),
      onSuccess: (term) =>
        browserApiClient.pipe(
          Effect.flatMap((client) => readDocsSearch(client, term)),
          Effect.map((found) => ({ _tag: "Found" as const, ...found, term }))
        ),
    }),
  });

