        TaxKitRpcClient.of({
          calculate: Effect.fn("TaxKitRpcClient.calculate")(() =>
            Effect.sync(started).pipe(
              Effect.andThen(Effect.never),
              Effect.onInterrupt(() => Effect.sync(cancelled))
            )
          ),
