});
const promiseBoundarySchema = [
  {
    type: "object",
    properties: {
      allowedFiles: { type: "array", items: { type: "string" } },
      promiseOnlyFiles: { type: "array", items: { type: "string" } },
    },
    required: ["allowedFiles"],
    additionalProperties: false,
