import { Effect, Layer } from "effect";

import {
  GrossPayFact,
  NetPayFact,
  TaxablePayFact,
  TaxFreeThresholdClaimed,
  TaxFreeThresholdClaimedFact,
} from "../facts/pay.js";
import { PayWithholdingsLedgerFact } from "../facts/withholdings.js";
import { PayRulePackVersion, TakeHomePayReport } from "./schemas.js";
import type { TakeHomeScenarioInput } from "./schemas.js";

export {
  TakeHomePayReport,
  TakeHomeScenarioInputSchema,
  type TakeHomeScenarioInput,
} from "./schemas.js";

export { PayWithholdingsLedgerFact as CalculatePayWithholdings } from "../facts/withholdings.js";

/**
 * Calculates the take-home pay report from the facts supplied by a rule pack.
 *
 * Requires the derived `TaxablePayFact`, `PayWithholdingsLedgerFact`, and
 * `NetPayFact`; scenario input is supplied separately by `TakeHomeScenarioLive`.
 *
 * @since 0.1.0
 */
import { Cents, Money } from "@taxkit/core/primitives";
import { Effect, Layer } from "effect";

import {
  AnnualTaxableIncome,
  AnnualTaxableIncomeFact,
} from "../facts/income.js";
import { AnnualTaxLedgerFact } from "../facts/ledger.js";
import { AnnualTaxReport, AnnualTaxRulePackVersion } from "./schemas.js";
import type { AnnualTaxScenarioInput } from "./schemas.js";

export {
  AnnualTaxReport,
  AnnualTaxScenarioInputSchema,
  type AnnualTaxScenarioInput,
} from "./schemas.js";

/**
 * Calculates annual income tax from the supplied taxable income and derived
 * annual tax ledger.
 *
 * @since 0.1.0
 */
export const CalculateAnnualTax = Effect.gen(function* () {
  const income = yield* AnnualTaxableIncomeFact;
  const ledger = yield* AnnualTaxLedgerFact;

  const { rawLiability } = ledger;
  const liability =
    rawLiability.cents < 0
      ? new Money({ cents: Cents.make(0), currency: "AUD" })
      : rawLiability;

  return new AnnualTaxReport({
    ledger,
